        {
          "link": "cafe_visitor_unaffected",
          "basis": "dossier_fact",
          "claim": "The walk-in café customer (m1.buyer.a3) is the intended beneficiary of the capacity reservation; their occasion (d.buyer.b6) is not degraded. No change to their routine is adjudicated.",
          "cite": ["d.buyer.b6"]
        },
        {
          "link": "mobile_slot_pressure_trigger",
          "basis": "judgment",
          "claim": "Whether habitual-app users (m1.buyer.a1) and commuters (m1.buyer.a2) encounter pickup times beyond their stated thresholds depends on how full the mobile allocation becomes during January peak windows. If the 80% mobile-plus-café residual is sufficient to meet demand without queue pressure, neither switching threshold is reached in January. If demand is high relative to the mobile allocation, slots push out and thresholds are crossed. This is the central unresolved branch for move one."
        },
        {
          "link": "habitual_app_switching_path",
          "basis": "dossier_fact",
          "claim": "If the habitual-app user (m1.buyer.a1) encounters two >8-minute delays in a week, they redirect daily spend to Dutch Bros or Dunkin for the remainder of the month. Loyalty friction exists but its monetary magnitude and prevalence are unstated (d.buyer.b5). No segment count is available.",
          "cite": ["d.buyer.b5"]
        },
        {
          "link": "commuter_abandonment_path",
          "basis": "dossier_fact",
          "claim": "If the commuter (m1.buyer.a2) receives a slot that consumes the 10-minute travel slack, they abandon and drive to the nearest competitor drive-through. Two such events make that competitor the new default. The trigger depends on the slot time offered, which depends on unresolved baseline capacity (d.buyer.b4).",
          "cite": ["d.buyer.b4"]
        },
        {
          "link": "competitor_absorption",
          "basis": "dossier_fact",
          "claim": "Buyer dossier assumes Dutch Bros Order Ahead and Dunkin app are available as alternatives at participating locations (d.buyer.b2). Actual local availability is location-dependent and unconfirmed for every pilot café neighborhood.",
          "cite": ["d.buyer.b2"]
        }
      ],
